mapper.select:
select 
        from p_skill s where s.status!='DELETED' and (s.account_id=#{accountId} or s.visibility='OFFICIAL')
        order by s.visibility asc,s.created_at desc,s.id desc limit #{limit} offset #{offset}

select count(*) from p_resource_reference r
        join p_app_config c on c.id=r.resource_id and c.application_id=#{applicationId}
        join p_application a on a.id=c.application_id and a.account_id=#{accountId}
          and a.status='ACTIVE' and a.admin_disabled=0
        join sys_user u on u.user_id=a.account_id and u.status='0' and u.del_flag='0'
        join p_app_skill x on x.app_config_id=c.id and x.skill_version_id=#{versionId} and x.enabled=1
        where r.account_id=#{accountId} and r.holder_type='SESSION' and r.holder_id=#{sessionId}
          and r.resource_type='APP_CONFIG' and r.state='CONFIRMED'

mapper.update:
update p_skill set current_version_id=#{versionId},status='PUBLISHED',revision=revision+1,
        updated_at=utc_timestamp(3) where id=#{skillId} and account_id=#{accountId} and revision=#{revision}
        and status not in ('DISABLED','DELETED')
